import assert from 'node:assert/strict';
import {initializeRechargeModel,nextRechargeState} from '../../app/lib/zeshu-pay-recharge-state.ts';
import {readFileSync} from 'node:fs';
const transact=(state,event)=>nextRechargeState(state,event);
const shouldReject=(state,event)=>assert.throws(()=>transact(state,event),/RECHARGE_TRANSITION_DENIED/);
const orderId='order_TEST_12345678',paymentId='pay_TEST_12345678',requestId='ZMRTEST_ORDER_12345678';
let tx=initializeRechargeModel(orderId);
shouldReject(tx,{type:'PROVIDER_SUBMITTED',requestId});
shouldReject(tx,{type:'GATEWAY_PAYMENT_VERIFIED',orderId:'order_OTHER_12345678',paymentId});
tx=transact(tx,{type:'PAYMENT_STARTED'});
tx=transact(tx,{type:'GATEWAY_PAYMENT_VERIFIED',orderId,paymentId});
assert.equal(tx.state,'PAYMENT_VERIFIED');
shouldReject(tx,{type:'GATEWAY_PAYMENT_FAILED'});
tx=transact(tx,{type:'PROVIDER_SUBMITTED',requestId});
assert.equal(tx.providerRequestId,requestId);
assert.equal(tx.state,'PROVIDER_PENDING');
shouldReject(tx,{type:'PROVIDER_SUBMITTED',requestId:'ZMRTEST_DUPLICATE_12345678'});
tx=transact(tx,{type:'PROVIDER_TIMEOUT'});
assert.equal(tx.state,'PROVIDER_UNKNOWN');
shouldReject(tx,{type:'PROVIDER_SUBMITTED',requestId:'ZMRTEST_RETRY_12345678'});
shouldReject(tx,{type:'PROVIDER_RESULT_VERIFIED',requestId:'WRONG_PROVIDER_REQUEST',result:'SUCCESS',receiptId:'OPERATOR_12345678'});
shouldReject(tx,{type:'PROVIDER_RESULT_VERIFIED',requestId,result:'SUCCESS'});
const pending=transact(tx,{type:'PROVIDER_RESULT_VERIFIED',requestId,result:'PENDING'});
assert.equal(pending.state,'PROVIDER_UNKNOWN');
tx=transact(tx,{type:'PROVIDER_RESULT_VERIFIED',requestId,result:'SUCCESS',receiptId:'OPERATOR_12345678'});
assert.equal(tx.state,'COMPLETED');
shouldReject(tx,{type:'PROVIDER_SUBMITTED',requestId:'ZMRTEST_RESUBMIT_12345678'});
shouldReject(tx,{type:'PROVIDER_RESULT_VERIFIED',requestId,result:'FAILED'});
let failure=transact(initializeRechargeModel('order_TEST_FAIL123'),{type:'PAYMENT_STARTED'});
failure=transact(failure,{type:'GATEWAY_PAYMENT_FAILED'});
assert.equal(failure.state,'FAILED');
shouldReject(failure,{type:'PROVIDER_SUBMITTED',requestId});
let refund=transact(initializeRechargeModel('order_TEST_REFUND123'),{type:'GATEWAY_PAYMENT_VERIFIED',orderId:'order_TEST_REFUND123',paymentId});
refund=transact(refund,{type:'PROVIDER_SUBMITTED',requestId});
refund=transact(refund,{type:'PROVIDER_RESULT_VERIFIED',requestId,result:'FAILED'});
assert.equal(refund.state,'REFUND_PENDING');
shouldReject(refund,{type:'PROVIDER_SUBMITTED',requestId});
refund=transact(refund,{type:'REFUND_RESULT_VERIFIED',refundId:'REFUND_TEST_12345678'});
assert.equal(refund.state,'REFUNDED');
const route=readFileSync('app/api/process-recharge/route.ts','utf8');
assert(route.includes("fulfillment: 'UNAVAILABLE'"));
assert(route.includes("{ status: 503 }"));
const admin=readFileSync('app/api/admin/pay/readiness/route.ts','utf8');
assert(admin.includes('approvedToGoLive:false'));
assert(!admin.includes('nextRechargeState('),'State design cannot accidentally process a live recharge');
console.log('PASS: payment proof, unique submission, unknown-no-retry, authoritative provider success and refund states are modeled without money or live API calls.');
